function failure(e){if(e?.message==='ORDER_NOTE_ENGLISH_ONLY'){say(requestNoteMessage(t),true);return;}const workflowMessage=workflowError(e,t);if(workflowMessage){say(workflowMessage,true);return;}if(e?.code==='email_not_confirmed'){say(t('이메일 인증이 아직 완료되지 않았어요. 가입할 때 받은 인증메일의 링크를 누른 뒤 다시 로그인해 주세요. 관리자 승인을 받았어도 이메일 인증은 필요합니다. 스팸함도 확인해 주세요.','Your email is not verified yet. Open your signup confirmation link, then sign in again. Email verification is required even after manager approval. Check your spam folder too.'),true);return;}if(e?.code==='over_email_send_rate_limit'){say(t('인증메일 발송 한도에 도달했어요. 가입 버튼을 반복해서 누르지 말고 관리자에게 알려 주세요.','The email sending limit has been reached. Contact an administrator instead of repeatedly submitting.'),true);return;}if(e?.code==='invalid_credentials'){say(t('이메일 또는 비밀번호가 맞지 않아요. 저장된 암호를 자동 완성했다면 취소하고 직접 입력해 주세요. 처음 로그인한다면 가입 인증메일도 확인해 주세요.','Email or password is incorrect. If you used a saved password, cancel autofill and enter it manually. For first sign-in, also verify your signup email.'),true);return;}if(e?.message==='DATE_REQUIRED'||e?.message==='DATE_PAST'||e?.message==='Delivery must be tomorrow or later'){uncertain=false;cartOpen=true;say(t('입고희망일을 다시 선택해 주세요. 담은 품목은 그대로 유지됩니다.','Choose a valid delivery date. Your basket items are preserved.'),true);return;}if(e?.message==='EMPTY_ORDER'){say(t('발주함에 품목을 담아 주세요.','Add items to the basket first.'),true);return;}if(e?.message==='INVALID_QUANTITY'){say(t('수량은 0 이상의 정수로 입력해 주세요. 품목 단위도 확인해 주세요.','Use whole-number quantities and check item units.'),true);return;}if(e?.message?.startsWith('BASKET_')||e?.message==='ALREADY_SUBMITTED'){say(t('다른 직원이 같은 품목·날짜를 수정하거나 발주를 완료했어요. 현재 입력은 유지했으니 최신 자료를 불러와 비교해 주세요.','A colleague changed this item/date or submitted the basket. Your edits remain here; reload to compare.'),true);return;}if(e?.message==='Email verification required'){say(t('가입자가 이메일 확인을 마친 뒤 승인해 주세요.','Approve after the employee verifies their email.'),true);return;}if(['Access blocked','Protected account','Outside managed stores'].includes(e?.message)){say(t('이 계정 또는 근무지는 현재 권한으로 처리할 수 없어요. 최종관리자에게 문의해 주세요.','Your role cannot change this account or workplace. Contact the owner.'),true);return;}if(e?.message==='RECEIPT_UNCHECKED'){say(t('각 품목에 입고확인·미입고를 선택해 주세요. 일부만 받았다면 실제 받은 수량을 입력하세요.','Choose Received or Not received for each item. For partial deliveries, enter the actual quantity.'),true);return;}if(e?.message==='STORE_UNAVAILABLE'){say(t('이 매장에서 발주할 수 없는 품목이 발주함에 있어요. 발주함을 열어 해당 품목을 제거해 주세요. 크림밤은 미드랜드 전용입니다.','Your basket contains an item unavailable at this store. Open the basket and remove it. Kream bombs are Midland-only.'),true);cartOpen=true;renderCart();return;}if(['RECEIPT_INVALID','RECEIPT_EMPTY','GUIDE_CONFLICT'].includes(e?.message)){say(e.message==='GUIDE_CONFLICT'?t('문서가 다른 기기에서 변경되었어요. 입력을 복사해 둔 뒤 최신 문서를 불러와 주세요.','Document changed on another device. Copy your edits before reloading.'):t('실제 받은 수량을 입력해 주세요. 미입고 수량보다 많게 입력할 수 없어요.','Enter quantities actually received, up to the outstanding amount.'),true);return;}if(e?.message==='DISPATCH_UNCHECKED'||e?.message==='INVALID_DISPATCH'){say(t('모든 품목에 출고확인·출고하지 않음을 선택하거나 실제 출고량을 입력해 주세요.','Check every dispatch item and its actual quantity. For unsent items, check and enter 0.'),true);return;}console.error('Kream request failed',e?.code||e?.message);const conflict=e?.message==='DRAFT_CONFLICT'||e?.code==='40001';say(conflict?t('다른 기기에서 자료가 변경되었습니다. 입력 내용은 유지했어요. 최신 자료를 불러온 뒤 확인해 주세요.','Data changed on another device. Your edits remain here. Reload cloud data to review.'):t('처리하지 못했어요. 연결 상태와 권한을 확인하고 다시 시도해 주세요.','Unable to complete. Check connection and access, then retry.'),true);}
async function result(query){const r=await query;if(r.error)throw r.error;return r.data;}
