function renderAuth(){
 if(signupNoticeEmail&&!user&&!recovery){$('#auth').innerHTML=`<div class="auth"><h1>${t('인증메일을 확인해 주세요','Check your confirmation email')}</h1><p>${t('가입 요청을 처리했어요. 아래 이메일의 받은편지함을 확인해 주세요.','Your signup request was processed. Check the inbox for the address below.')}</p><p><strong>${esc(signupNoticeEmail)}</strong></p><ol><li>${t('인증메일을 열고 확인 링크를 눌러 주세요.','Open the confirmation email and click its link.')}</li><li>${t('관리자가 근무지와 권한을 승인하면 업무 페이지를 이용할 수 있어요.','An administrator must also approve your workplace and access.')}</li></ol><p><strong>${t('관리자 승인을 받았어도 이메일 인증을 마쳐야 로그인할 수 있어요.','Even after administrator approval, you must verify your email before signing in.')}</strong></p><p class="muted">${t('메일이 보이지 않으면 스팸함도 확인해 주세요.','If you cannot find the email, check your spam folder.')}</p><button id="backToLogin" class="primary" type="button">${t('인증 후 로그인하기','Sign in after verification')}</button></div>`;$('#backToLogin').onclick=()=>{signupNoticeEmail='';mode='login';say('');render();};return;}

 if(user&&!profile?.active&&!recovery){$('#auth').innerHTML=`<div class="auth"><h1>${t('매장 배정을 기다리고 있어요','Waiting for access')}</h1><p>${t('계정은 로그인되어 있어요. 관리자가 직원 권한과 매장을 배정하면 발주할 수 있습니다.','You are signed in. An administrator must assign your role and store before you can order.')}</p><div id="pendingWorkplaces"></div><button id="checkAccess">${t('배정 확인','Check access')}</button></div>`;$('#checkAccess').onclick=()=>run(loadIdentity);renderWorkplaces($('#pendingWorkplaces'),{db,t,esc,act:run,say});return;}
 const title=recovery?t('새 비밀번호 설정','Set a new password'):mode==='signup'?t('직원 계정 만들기','Create a staff account'):mode==='reset'?t('비밀번호 찾기','Reset password'):t('직원 로그인','Staff sign in');
 $('#auth').innerHTML=`<div class="auth"><h1>${title}</h1><p class="muted">${t('매장과 공장을 잇는 크림 운영 공간','The workspace connecting Kream stores and factory')}</p><form id="authForm">${recovery?'':`<label>${t('이메일','Email')}<input id="authEmail" name="email" type="email" value="${esc(authEmail)}" autocomplete="${mode==='login'?'username':'email'}" autocapitalize="none" autocorrect="off" spellcheck="false" required></label>`}${mode==='reset'&&!recovery?'':`<label>${t('비밀번호','Password')}<input id="authPassword" name="password" type="password" minlength="8" autocomplete="${mode==='login'&&!recovery?'current-password':'new-password'}" required></label>`}${mode==='signup'&&!recovery?`<label>언어 / Language<select name="preferredLanguage"><option value="ko" ${lang==='ko'?'selected':''}>한국어</option><option value="en" ${lang==='en'?'selected':''}>English</option></select></label><label>${t('기록에 남길 이름','Your name')}<input name="displayName" maxlength="120" required></label><fieldset><legend>${t('근무지 선택 · 복수 선택 가능','Workplaces · select all that apply')}</legend>${workplaceChoices(signupLocations,t,esc,signupWorkplaces)}</fieldset><p>${t('이메일 확인 후 각 근무지 관리자의 승인이 필요합니다.','Each workplace needs manager approval after email verification.')}</p>`:''}<button class="primary">${!recovery&&mode==='login'?t('로그인','Sign in'):title}</button></form>${recovery?'':`<div class="links">${mode==='login'?'':`<button data-mode="login">${t('로그인','Sign in')}</button>`}<button data-mode="signup">${t('계정 만들기','Sign up')}</button><button data-mode="reset">${t('비밀번호 찾기','Reset password')}</button></div>`}<p class="muted">${t('신규 가입만으로 매장 자료에 접근할 수 없어요. 관리자 배정이 필요합니다.','Signing up does not grant access to store data. Administrator assignment is required.')}</p></div>`;
 document.querySelectorAll('[data-mode]').forEach(b=>b.onclick=()=>{mode=b.dataset.mode;if(mode==='signup'&&!signupLocations.length){db.rpc('kream_signup_locations').then(r=>{if(!r.error){signupLocations=r.data||[];render();}else say(t('근무지 목록을 불러오지 못했어요.','Unable to load workplaces.'),true);});}render();});
 $('#authEmail')?.addEventListener('input',e=>{authEmail=e.target.value;});
 $('#authForm').onsubmit=e=>{e.preventDefault();const form=new FormData(e.target);run(async()=>{
 const email=String(form.get('email')||'').trim(),password=String(form.get('password')||'');authEmail=email;
 const redirect=location.origin+location.pathname;
 if(recovery){await result(db.auth.updateUser({password}));recovery=false;await loadIdentity();say(t('비밀번호를 변경했어요.','Password updated.'));}
 else if(mode==='signup'){signupWorkplaces=form.getAll('workplaces');if(!signupWorkplaces.length){say(t('근무지를 한 곳 이상 선택해 주세요.','Select at least one workplace.'),true);return;}lang=form.get('preferredLanguage')==='en'?'en':'ko';localStorage.setItem('kream-staff-language',lang);await result(db.auth.signUp({email,password,options:{emailRedirectTo:redirect,data:{preferred_language:lang,workplaces:signupWorkplaces,display_name:String(form.get('displayName')||'').trim()}}}));signupNoticeEmail=email;mode='login';showSignupNotice(email,{t,esc});await loadIdentity();say(t('가입 후 이메일 인증이 필요해요. 인증메일의 링크를 눌러 주세요.','Verify your email after signup by opening the confirmation link.'));}
 else if(mode==='reset'){await result(db.auth.resetPasswordForEmail(email,{redirectTo:redirect}));say(t('이메일을 확인해 주세요. 비밀번호 설정 링크를 요청했어요.','Check your email for the password reset link.'));}
 else{await result(db.auth.signInWithPassword({email,password}));await loadIdentity();say(t('로그인했어요.','Signed in.'));}
 });};
}
$('#myName').onclick=()=>{if(busy||isPreview())return;openMyAccount({db,profile,lang,t,esc,onSaved:({displayName,language})=>{profile={...profile,display_name:displayName};lang=language;user={...user,user_metadata:{...user.user_metadata,preferred_language:lang}};localStorage.setItem('kream-staff-language',lang);render();say(t('내 정보를 저장했어요.','Your account settings are saved.'));}});};
let workflowSourceTimer=null;
function refreshWorkflowSources(){clearTimeout(workflowSourceTimer);const sourcePage=page;workflowSourceTimer=setTimeout(async()=>{if(page!==sourcePage||!['dispatch','receiving'].includes(page))return;if(busy){refreshWorkflowSources();return;}try{await loadOrders();await loadModules();if(page===sourcePage)render();}catch(e){failure(e);}},250);}
async function run(fn){if(busy)return;if(isPreview()){say(t('권한 미리보기에서는 저장·발주·입고 확인을 실행하지 않아요. 실제 화면으로 돌아가 주세요.','Preview mode cannot save, submit or receive. Return to the live workspace.'),true);return;}setBusy(true);try{await fn();}catch(e){failure(e);}finally{setBusy(false);}}
function isPreview(){return canPreview(profile,previewRole);}
function screenRole(){return isPreview()?previewRole:profile?.role==='manager'&&profile.general_manager?'general_manager':profile?.role==='factory'?accountKind(profile):profile?.role;}
function screenProfile(){if(!isPreview())return combinedKinds.includes(screenRole())?{...profile,role:(['factoryreservations','factorymanual','production','dispatch','galleria','galleriaHistory','galleriaSop','externaldispatch','productionlog','finishedstock','costs','inventory','purchases','materialreceiving'].includes(page)||['waste','sop'].includes(page)&&combinedArea==='factory'||page==='hr'&&(screenRole()==='employee_factory_manager'||entryFactory&&profile.factory_manager))?'factory':profile.store_manager?'manager':'employee'}:profile;const selected=previewRoles.find(r=>r[0]===previewRole);return {...profile,role:isFactoryRole(previewRole)?'factory':previewRole==='general_manager'?'manager':previewRole,general_manager:previewRole==='general_manager',display_name:t(selected[1],selected[2])+' · '+t('미리보기','Preview')};}
function screenStores(){if(!isPreview()&&combinedKinds.includes(screenRole())&&!['factoryreservations','factorymanual','production','dispatch','galleria','galleriaHistory','galleriaSop','externaldispatch','productionlog','finishedstock','costs','inventory','purchases','materialreceiving'].includes(page))return stores.filter(s=>(profile.store_ids||[]).includes(s.id));return isPreview()&&!isFactoryRole(previewRole)&&previewRole!=='general_manager'?stores.filter(s=>s.id===store):stores;}
function snapshotOwner(){return {store,date,productionDate,overviewDate,note,dirty,uncertain,quantities:{...quantities},orders,stock,draft,category,search,subgroup,filter,page,cartOpen,receipts,guides,receiptOrders,waste,dispatches};}
function restoreOwner(){if(!ownerView)return;({store,date,productionDate,overviewDate,note,dirty,uncertain,quantities,orders,stock,draft,category,search,subgroup,filter,page,cartOpen,receipts,guides,receiptOrders,waste,dispatches}=ownerView);ownerView=null;previewRole='';clearModuleState();}
function changePreview(role,targetStore=store){
 if(busy||profile?.role!=='owner'||!profile.active)return;
 if(!isPreview()&&hasModuleEdits()){say(t('작성 중인 문서나 입고 입력을 저장하거나 닫은 뒤 미리보기를 선택해 주세요.','Save or close document/receipt edits before entering preview.'),true);render();return;}
 if(role==='owner'){restoreOwner();say('');render();return;}
 if(!canPreview(profile,role))return;
 if(!ownerView)ownerView=snapshotOwner();
 previewRole=role;store=role==='midland_owner'?'midland':stores.some(s=>s.id===targetStore)?targetStore:(stores[0]?.id||'');
 clearModuleState();const scoped=scopePreview(role,store,{orders:ownerView.receiptOrders,receipts:ownerView.receipts,guides:ownerView.guides});
 orders=scoped.orders;receiptOrders=scoped.orders;receipts=scoped.receipts;guides=scoped.guides;dispatches=ownerView.dispatches.filter(d=>isFactoryRole(role)||d.store_id===store);waste=ownerView.waste.filter(w=>isFactoryRole(role)?w.location_kind==='factory':w.location_kind==='store'&&w.store_id===store);
 stock=store===ownerView.store?ownerView.stock:[];draft=null;quantities={};date=defaultReceiptDate();note='';dirty=false;uncertain=false;category='';subgroup='';filter='all';search='';cartOpen=false;
 productionDate=tomorrowToronto();page=isFactoryRole(role)?'production':'order';say('');render();
}
function previewControls(){if(profile?.role!=='owner'||!profile.active)return '';const factory=isFactoryRole(screenRole());return `<section class="role-preview ${isPreview()?'preview-on':''}" aria-label="${t('권한별 화면 미리보기','Role preview')}"><div class="preview-fields"><label>${t('접속자 권한 미리보기','Preview role')}<select id="previewRole">${previewRoles.map(r=>`<option value="${r[0]}" ${(previewRole||'owner')===r[0]?'selected':''}>${t(r[1],r[2])}</option>`).join('')}</select></label><label>${t('미리볼 매장','Preview location')}<select id="previewStore" ${!isPreview()||factory||previewRole==='midland_owner'?'disabled':''}>${stores.map(s=>`<option value="${esc(s.id)}" ${s.id===store?'selected':''}>${esc(s.name)}</option>`).join('')}</select></label>${isPreview()?`<button id="exitPreview">${t('최종관리자 실제 화면으로','Return to owner workspace')}</button>`:''}</div><p>${isPreview()?t('화면 미리보기 중 · 실제 계정 권한은 바뀌지 않습니다. 저장·발주·입고 기록은 실행되지 않으며 입력은 미리보기용입니다.','Preview only. Your account role is unchanged. Saving, ordering and receiving are blocked; inputs are temporary.'):t('권한과 매장을 선택해 직원에게 보이는 화면을 확인하세요.','Choose a role and location to inspect the staff interface.')}</p>${factory&&isPreview()?`<p class="muted">${t('공장 직원·매니저 모두 생산·재고·폐기 기록을 사용합니다. 장보기(발주확인)은 공장 매니저에게만 표시됩니다. 실제 계정의 매니저 지정은 관리자 배정에 따릅니다.','Both factory roles can record production, stock and waste. Only factory managers see purchasing. Live manager access requires administrator assignment.')}</p>`:''}</section>`;}
function bindPreview(){if($('#previewRole'))$('#previewRole').onchange=e=>changePreview(e.target.value);if($('#previewStore'))$('#previewStore').onchange=e=>changePreview(previewRole,e.target.value);if($('#exitPreview'))$('#exitPreview').onclick=()=>changePreview('owner');}
function applyPreviewReadOnly(){if(!isPreview())return;for(const id of ['save','submit','newOrder','refresh','confirmReceipt','saveWaste']){const el=document.querySelector('#'+id);if(el){el.disabled=true;el.title=t('미리보기에서는 실행되지 않아요.','Disabled in preview.');}}document.querySelectorAll('#guideForm button[type="submit"]').forEach(el=>{el.disabled=true;});}
async function loadIdentity(){
 const epoch=++generation;const {data,error}=await db.auth.getUser();if(epoch!==generation)return;
 if(error||!data.user){previewRole='';ownerView=null;clearModuleState();user=null;profile=null;stores=[];catalog=[];receipts=[];guides=[];receiptOrders=[];waste=[];dispatches=[];layoutRows=[],stockRules=[];catalogAll=[];photoURLs={};deliveryPrices=[];draft=null;orders=[];quantities={};dirty=false;uncertain=false;return;}
 const freshUser=data.user;if(user?.id!==freshUser.id){previewRole='';ownerView=null;clearModuleState();}
 const freshProfile=await result(db.from('kream_profiles').select('user_id,display_name,role,active,factory_manager,general_manager,store_manager').eq('user_id',freshUser.id).maybeSingle());
 if(epoch!==generation)return;user=freshUser;profile=freshProfile;if(['ko','en'].includes(user.user_metadata?.preferred_language)){lang=user.user_metadata.preferred_language;localStorage.setItem('kream-staff-language',lang);}
 if(!profile?.active){stores=[];catalog=[];orders=[];return;}
 {const memberships=await result(db.from('kream_memberships').select('store_id').eq('user_id',user.id));profile.store_ids=memberships.map(m=>m.store_id);}
 const s=await result(db.from('kream_stores').select('id,name').eq('active',true).order('name'));await loadCatalog();
 if(epoch!==generation)return;stores=s.sort((a,b)=>storeRank(a)-storeRank(b));const choices=assignedWorkplaces(profile,stores);const assigned=choices.stores;const entry=isPreview()?null:await chooseWorkplace({...choices,hr:canUseHR(profile,accountKind(profile)),lang,userId:user.id});if(epoch!==generation)return;entryFactory=!!entry?.factory;if(entry?.storeId)store=entry.storeId;store=assigned.some(s=>s.id===store)?store:(assigned[0]?.id||'');
 if(stores.length&&stores.every(s=>s.id.startsWith('galleria-')))page='galleria';else if(profile.role==='factory'&&!(profile.store_ids||[]).length)page='production';if(entry?.factory)page='production';else if(entry?.storeId)page=entry.storeId.startsWith('galleria-')?'galleria':'order';if(entry?.hr)page='hr';{const go=new URLSearchParams(location.search).get('go');if(['hr','team','cash','order'].includes(go))page=go;}await loadOrders();await loadModules();if((profile.role!=='factory'||(profile.store_ids||[]).length)&&store)await loadDraft();
}
function groupedOrder(o){return {...o,kream_order_items:sortProductRows(o.kream_order_items||[],catalogAll)};}
async function loadCatalog(){catalogAll=await result(db.from('kream_catalog').select('id,name_ko,name_en,category,subgroup,order_unit,unit_confirmed,active,archived,photo_path,production_team,factory_subgroup,revision').order('name_ko').limit(1000));catalogAll=sortCatalog(catalogAll);catalog=catalogAll.filter(p=>p.active&&!p.archived);photoURLs=await signedPhotos(db,catalog);if(category&&!(store==='finch'&&category==='키친 발주')&&!catalog.some(p=>p.category===category)){category='';subgroup='';}}
function orderCatalog(){return storeCatalog(catalog,store);}
function orderItems(){if(catalog.some(p=>Number(quantities[p.id])>0&&!availableForStore(p,store)))throw new Error('STORE_UNAVAILABLE');return validItems(quantities,orderCatalog());}
function catalogContext(){return {catalog:orderCatalog(),catalogAll:storeCatalog(catalogAll,store),photoURLs,category,profile:screenProfile(),store,lang,t,esc,name,db,act:run,say,preview:isPreview(),reload:loadCatalog};}
// Track quantities generated on this device for the exact saved basket revision.
function readBasketRecommendations(saved){
 if(!saved?.id||store==='midland')return {};
 try {const record=JSON.parse(localStorage.getItem('kream-basket-recommendations:'+store)||'null');return record?.id===saved.id&&record.revision===saved.revision?record.quantities:{};} catch {return {};}
}
function rememberBasketRecommendations(saved){
 if(!saved?.id||store==='midland')return;
 const matched=Object.fromEntries(saved.items.filter(i=>autoAssigned[i.product_id]===Number(i.quantity)).map(i=>[i.product_id,Number(i.quantity)]));
 try {localStorage.setItem('kream-basket-recommendations:'+store,JSON.stringify({id:saved.id,revision:saved.revision,quantities:matched}));} catch {}
 autoAssigned=matched;
}
function applyLoadedDraft(saved){draft=saved;quantities=Object.fromEntries((draft?.items||[]).map(i=>[i.product_id,i.quantity]));date=restoredReceiptDate(draft);note=draft?.note||'';dirty=!!draft&&date!==draft.delivery_date;uncertain=false;autoAssigned=readBasketRecommendations(draft);}
