async function loadOrders(){let q=db.from('kream_orders').select('id,store_id,delivery_date,note,status,dispatch_finalized_at,created_at,source_kind,order_revision,amended_at,amended_by,kream_order_items(product_id,name_ko,name_en,order_unit,quantity)').order('created_at',{ascending:false}).order('id');if((profile.role!=='factory'||(profile.store_ids||[]).length)&&store)q=q.eq('store_id',store);orders=(await readAllRows(()=>q)).map(groupedOrder);deliveryPrices=await readPrices(db,profile,'midland');stock=store?await result(db.from('kream_stock').select('product_id,on_hand,minimum,revision,updated_at,physical_count_at').eq('store_id',store)):[];try{weeklyReviews=store?await result(db.from('kream_weekly_order_reviews').select('store_id,product_id,next_review_date,checked_at').eq('store_id',store)):[];weeklyReviewsError=false;}catch{weeklyReviews=[];weeklyReviewsError=true;} }
function storeRank(s){const n=(s.id+' '+s.name).toLowerCase();return ['finch','wellesley','downtown','midland','richmond','k-town','ktown','york'].findIndex(k=>n.includes(k))<0?99:['finch','wellesley','downtown','midland','richmond','k-town','ktown','york'].findIndex(k=>n.includes(k));}
const pages=[['clover','🍀','판매·재고 연결','Sales & stock sync'],['galleria','🚚','출고준비','Dispatch preparation'],['galleriaHistory','🧾','출고기록','Dispatch records'],['galleriaSop','📖','판매기한/라벨 SOP','Shelf life / label SOP'],['factorymanual','📋','공장운영 매뉴얼','Factory operations manual'],['catalogreview','▦','품목관리 · 분류 검수','Item classification'],['order','＋','매장 발주','Store order'],['history','☷','발주 확인','Order history'],['reservations','✉','예약주문 확인','Pickup orders'],['factoryreservations','✉','예약주문 확인','Pickup orders'],['production','◷','생산·배분','Production'],['productionlog','✍','생산기록','Production records'],['finishedstock','▦','완제품 재고관리','Finished stock'],['receiving','✓','입고확인','Receiving'],['sop','☑','SOP','SOP'],['manual','▥','매장운영 매뉴얼','Store operations manual'],['dispatch','▣','출고 준비','Dispatch'],['costs','🧮','원가','Costing'],['externaldispatch','📤','기타 출고','External dispatch'],['purchases','▦','장보기(발주확인)','Purchases needed'],['materialreceiving','✓','원재료 입고확인','Material receiving'],['inventory','◎','원재료·소모품 재고 / 발주','Materials & supplies · stock / orders'],['waste','▤','폐기기록','Waste log'],['hr','📊','HR 관리','HR Management'],['team','📅','스케줄','Schedule'],['cash','💵','Cash$','Cash$'],['daily','▧','운영일지','Daily log'],['settlement','₩','납품 정산','Settlement'],['overview','◫','운영 현황','Overview'],['accounts','⚙','가입 승인·접근 관리','Approvals & access']];
function renderWorkplaceBadge(){const host=$('#navigation');if(!profile?.active||isPreview())return;const html=workplaceBadge({store:stores.find(s=>s.id===store),factory:entryFactory,lang});if(!html)return;host.insertAdjacentHTML('afterbegin',html);bindWorkplaceSwitch(host,()=>{if(busy||uncertain)return;if((dirty||hasModuleEdits())&&!confirm(t('저장하지 않은 변경을 두고 근무지를 바꿀까요?','Leave unsaved changes and switch workplaces?')))return;cancelBasketSave();run(async()=>{clearWorkplaceChoice(user.id);clearModuleState();await loadIdentity();});});}
function renderNav(){const host=$('#navigation'),vp=screenProfile(),role=screenRole();const button=p=>navigationTile(p,page,t);host.innerHTML=profile?.active?`<p class="tagline">${t('우리 매장과 공장을 잇는 곳','Connecting our stores and factory')}</p><nav class="nav-tiles ${['owner',...combinedKinds].includes(role)?'owner-navigation':''}">${navigationGroups(pages.filter(p=>!(store==='midland'&&['team','cash'].includes(p[0]))).filter(p=>!['galleria','galleriaHistory','galleriaSop'].includes(p[0])||canUseGalleria({...vp,store_ids:screenStores().map(s=>s.id)})),role).map(g=>g.key==='overview'?g.pages.map(button).join(''):g.ko?`<section class="nav-group" aria-label="${t(g.ko,g.en)}"><h2>${t(g.ko,g.en)}</h2>${g.pages.map(button).join('')}</section>`:g.pages.map(button).join('')).join('')}</nav><p class="account">${esc(vp.display_name)}<br><small>${isPreview()?t('최종관리자 전용 미리보기','Owner-only preview'):t('계정 권한에 따라 자료가 표시됩니다.','Data follows your account permissions.')}</small></p>`:'';host.insertAdjacentHTML('afterbegin',`<label class="mobile-page-picker">${t('메뉴 이동','Go to menu')}<select id="mobilePage" aria-label="${t('메뉴 선택','Choose menu')}">${[...host.querySelectorAll('[data-page]')].map(b=>`<option value="${esc(b.dataset.page)}" ${b.dataset.page===page?'selected':''}>${esc(b.textContent.trim())}</option>`).join('')}</select></label>`);host.querySelector('#mobilePage').onchange=e=>host.querySelector(`[data-page="${e.target.value}"]`)?.click();host.querySelectorAll('[data-page]').forEach(b=>b.onclick=()=>{if(!isPreview()&&hasModuleEdits()&&!confirm(t('저장하지 않은 입력을 두고 이동할까요?','Leave unsaved module entries?')))return;if(hasModuleEdits())clearModuleState();page=b.dataset.page;render();requestAnimationFrame(()=>document.querySelector('main')?.scrollIntoView({block:'start',behavior:'instant'}));});}

