 const title=page==='orderSaved'?['orderSaved','','발주함 저장 완료','Basket saved']:page==='orderComplete'?['orderComplete','','발주 완료','Order submitted']:pages.find(p=>p[0]===page)||pages[0];renderNav();renderWorkplaceBadge();
