function requestCurrentMidlandReview(){return run(async()=>{
 const items=orderItems();if(!items.length)throw Error('EMPTY_ORDER');if(!validDeliveryDate(date))throw Error('DATE_REQUIRED');
 if(!confirm(t('입고희망일: ','Requested receipt date: ')+fullDeliveryDate(date,lang)+'\n\n'+t('관리자에게 이 발주함의 검토를 요청할까요? 공장에는 아직 전송되지 않습니다.','Request manager review? This does not send the order to the factory.')))return;
 const beforeDate=date,beforeNote=note;await persistDraft();
 if(!sameBasketItems(items,draft.items)||draft.delivery_date!==beforeDate||draft.note!==beforeNote){cartOpen=true;say(t('다른 직원의 변경이 반영됐어요. 최신 발주함을 확인한 뒤 다시 검토 요청해 주세요.','Colleague changes were merged. Review the latest basket before requesting review.'));return;}
 draft=await requestMidlandReview(db,draft);dirty=false;showOrderConfirmation('review');
});}
