function draftStatus(){if($('#draftState'))$('#draftState').textContent=uncertain?t('전송 결과 확인 필요 · 같은 발주만 재시도하세요.','Submission not confirmed. Retry the same draft.'):dirty?t('저장하지 않은 변경','Unsaved changes'):draft?.store_id==='midland'&&draft.review_requested_at?t(draft.review_changed_since_request?'변경된 내용 있음 · 재검토 필요':'관리자 검토 대기',draft.review_changed_since_request?'Changed since review request':'Awaiting manager review'):draft?t(`공유 초안 · 버전 ${draft.revision}`,`Cloud draft · revision ${draft.revision}`):t('새 초안','New draft');}
