// 주문 단위를 쉬운 말로: 몇 '개'/'봉지'/'케이스' 세는지 알 수 있게
function unitWord(p){const u=String(p.order_unit||'').trim().toLowerCase();if(/^(ea|개|낱개)$/.test(u))return {ko:'개',en:'pieces'};if(/^bag|봉/.test(u))return {ko:'봉지',en:'bags',half:true};if(/^case/.test(u))return {ko:'케이스',en:'cases',half:true};if(/^box|박스/.test(u))return {ko:'박스',en:'boxes',half:true};if(/^(pack|팩)$/.test(u))return {ko:'팩',en:'packs'};if(/^set|세트/.test(u))return {ko:'세트',en:'sets'};if(/^tray/.test(u))return {ko:'트레이',en:'trays'};return {ko:String(p.order_unit||'개'),en:String(p.order_unit||'units')};}
